    answer: "GWP bedeutet Global Warming Potential. Das „Treibhauspotenzial\" oder „GWP\" steht für das Klimaerwärmungspotenzial eines Treibhausgases im Verhältnis zu dem von Kohlendioxid (CO2). Es wird ermittelt als das Erwärmungspotenzial eines Kilogramms eines Treibhausgases bezogen auf einen Zeitraum von 100 Jahren gegenüber dem entsprechenden Potenzial eines Kilogramms CO2.",
