    id: 247,
    block: "Anlagenkomponenten",
    question: "Wie funktioniert die Ölrückführung aus dem Flüssigkeitsabscheider in die Saugleitung und somit zum Verdichter?",
    answer: "Das Öl, welches im Flüssigkeitsabscheider liegen bleibt, wird durch eine Schnüffelbohrung feindosiert in die Saugleitung und somit zum Verdichter zurückgeführt.",
