    answer: "Eine dauerhaft heiße Ölrückführung ist ein Anzeichen dafür, dass Heißgas aus dem Ölabscheider in die Ölrückführung strömt. Gründe können ein hängender Schwimmer oder Fremdkörper zwischen der Düse und der Nadel im Ölabscheider sein. Abhängig von der Einbindung der Ölrückführung strömt das Heißgas in die Saugleitung oder in das Kurbelgehäuse, wodurch es zu Leistungsverlusten und zu hohen Verdichtungsendtemperaturen kommen kann.",
