    block: "Fehlersuche",
    question: "Der Verdichter einer Kälteanlage läuft im Winterbetrieb an und schaltet bereits nach kurzer Laufzeit über den Niederdruckschalter wieder aus. Was kann die Ursache sein und wie kann Abhilfe geschaffen werden?",
    answer: "Sinkt die Außentemperatur stark ab, so kann sich das Kältemittel in den Verflüssiger verlagern. Wenn in dieser Anlage keine Winterbetriebsdruckregelung verbaut ist, kommt es zu einem Absinken des Verflüssigungsdrucks. Wird die Mindestdruckdifferenz des Expansionsorganes unterschritten, so wird nicht mehr ausreichend Kältemittel in den Verdampfer eingespritzt, wodurch der Verdampfungsdruck absinkt. Sinkt dieser unter den Abschaltdruck des Niederdruckschalters, so wird die Anlage abgeschaltet. Abhilfe: Verflüssigungsdruckregelung einbauen.",
