    answer: "Mögliche Ursachen: Die Verflüssigeroberfläche ist zu groß → Verflüssigungsdruckregelung einbauen oder Verflüssiger austauschen. Der Verflüssigungsdruckregler ist auf einen zu niedrigen Druck eingestellt → richtig einstellen. Temperatur der Kühlluft zu niedrig → Drehzahlregelung des Motors einbauen. Luftmenge für den Verflüssiger zu groß → Ventilator gegen einen kleineren auswechseln.",
