    answer: "Das Abschalten der Anlage durch den Hochdruckschalter ist auf einen zu hohen Verflüssigungsdruck zurückzuführen. Ursachen: verschmutzte oder verstopfte Verflüssigeroberfläche, verstopfte Lüfter, ausbleibende Wasserversorgung, ausgelöste Sicherung zum Lüftermotor, zu hohe Kältemittelfüllmenge, nichtkondensierbare Fremdgase. Bei der Fehlerbehebung ist darauf zu achten, dass die Kälteanlage nicht eingeschaltet wird, bevor der Fehler gefunden und behoben wurde.",
