    question: "Wie muss die Brennerflamme beim Hartlöten richtig eingestellt werden?",
    answer: "Die Brennerflamme wird mit leichtem Gasüberschuss eingestellt (reduzierende Flamme). Damit wird die Oxidbildung im Bereich der Lötstelle minimiert und die Benetzbarkeit verbessert. Eine neutrale oder gar oxidierende Flamme würde Oxide fördern und die Fließfähigkeit des Lotes verschlechtern. Ziel ist, dass das Lot am Werkstück schmilzt und nicht in der Flamme verbrennt.",
